insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('301585b1-564c-5f77-a2fb-6362e7621995', '20503b30-2347-51fd-a078-27b8850c6557', '36f589e5-f924-501d-a645-dee9602ffde7', '522412a1-95b7-50ac-abc6-2019d98ff63a', 'Corporate social responsibility (CSR) means…', '["Paying the lowest wages possible","Following only shareholder wishes","A business considering its impact on society and the environment","Avoiding taxes legally"]'::jsonb, 'CSR goes beyond legal obligations.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
