insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('c84b2499-b5b9-54bc-a18d-883ab1aeeb88', '20503b30-2347-51fd-a078-27b8850c6557', '36f589e5-f924-501d-a645-dee9602ffde7', '522412a1-95b7-50ac-abc6-2019d98ff63a', 'Which is an example of conflict between stakeholders?', '["Shareholders want higher dividends while workers want higher wages","Customers and managers both want quality","Suppliers want to be paid on time","The government wants tax paid"]'::jsonb, 'Both demands compete for the same profits.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
