insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('095c75c9-32da-5770-ae4d-9d8d3cb21e02', '20503b30-2347-51fd-a078-27b8850c6557', 'dfb84fb6-ec45-5cea-a3aa-989757410b31', '28007b4a-5824-5d40-a74c-15eb9cf8d439', 'Mintzberg''s managerial roles are grouped as…', '["Financial, marketing and operations","Interpersonal, informational and decisional","Autocratic, democratic and laissez-faire","Planning, controlling and leading"]'::jsonb, 'Managers act as figureheads, monitors, negotiators and more.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
